import{_ as t,o,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Gemini 中式食品词的画面翻译","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-food-term-translation.md","filePath":"tools/gemini-food-term-translation.md","lastUpdated":1787456457000}'),d={name:"tools/gemini-food-term-translation.md"};function s(n,e,r,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="gemini-中式食品词的画面翻译" tabindex="-1">Gemini 中式食品词的画面翻译 <a class="header-anchor" href="#gemini-中式食品词的画面翻译" aria-label="Permalink to &quot;Gemini 中式食品词的画面翻译&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 对具体词汇的理解能力请以官方文档为准。</li></ul></div><blockquote><p>提问：中式食品的「锅气」「酥脆」「金黄」「挂汁」「焦香」这类词，拆成英文时该怎么落成 Veo 能真正理解的画面描述，而不是直译？能不能给几个标准对照？</p></blockquote><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h2><p>Veo 无法直接理解「锅气」这类文化概念，但它擅长渲染<strong>烟雾轨迹、液体黏度、微粒飞溅和高光反射</strong>。</p><p>所以拆法不是翻译，而是<strong>用物理运动 + 光影质感 + 物理材质 + 摄影语法去「还原现场」</strong>——把抽象的词落成模型能「看见」的画面。</p><h2 id="标准对照表" tabindex="-1">标准对照表 <a class="header-anchor" href="#标准对照表" aria-label="Permalink to &quot;标准对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文抽象词</th><th>直译误区（易忽略/变形）</th><th>物理还原逻辑</th><th>英文标准 Prompt 模板</th></tr></thead><tbody><tr><td>锅气</td><td><code>Wok hei</code> / <code>Wok flavor</code></td><td>热气升腾 + 冒烟 + 快速翻炒 + 油滴飞溅</td><td><code>Rising wisps of white steam, subtle smoke wafting, sizzling oil droplets, fast wok-tossing movement</code></td></tr><tr><td>酥脆</td><td><code>Crispy</code> / <code>Crunchy</code></td><td>碎屑飞溅 + 表面微孔裂纹 + 动态硬碰撞</td><td><code>Crumbles explosion in slow motion, crackling texture, micro-fractures on surface, light dust flying off</code></td></tr><tr><td>金黄</td><td><code>Golden yellow</code></td><td>焦糖色泽 + 边缘高光 + 侧逆光透光感</td><td><code>Deep golden-brown crust, backlit rim lighting, glistening amber tone, sun-kissed reflection</code></td></tr><tr><td>挂汁</td><td><code>Coated sauce</code></td><td>厚重液体慢速流动 + 粘稠包裹 + 镜面反光</td><td><code>Glossy thick sauce slowly dripping, velvety glaze clinging to the surface, mirror-like liquid sheen</code></td></tr><tr><td>焦香</td><td><code>Burnt fragrance</code></td><td>边缘微焦炭化 + 炙烤火苗 + 微微冒烟</td><td><code>Seared charred edges, caramelized golden crust, subtle flame kiss, light smoke rising</code></td></tr></tbody></table><h2 id="实战-prompt-案例" tabindex="-1">实战 Prompt 案例 <a class="header-anchor" href="#实战-prompt-案例" aria-label="Permalink to &quot;实战 Prompt 案例&quot;">​</a></h2><p><strong>1. 蜂蜜黄油味薯条（突出「金黄 / 酥脆 / 挂汁」）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extreme macro close-up, slow-motion 120fps. A crispy French fry with micro-cracks on its deep golden-brown crust. Melted honey-butter glaze clings velvet-smooth to the surface, dripping in slow motion. Fine amber sugar crystals and tiny butter droplets glisten under warm side-lighting. Soft cinematic focus, dark background.</span></span></code></pre></div><p>解析：用 <code>micro-cracks</code>（微裂纹）替代 <code>crispy</code>；用 <code>velvet-smooth</code>（丝绒顺滑）和 <code>dripping in slow motion</code>（超慢速滴落）描绘挂汁的黏稠感。</p><p><strong>2. 茄汁膨化零食 / 薯片（突出「浓郁挂汁 / 酸甜鲜红 / 咔哧酥脆」）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Macro lens, 4K commercial style. A crunchy tomato-flavored snack chip breaks in mid-air in super slow-motion, sending a tiny cloud of rich red seasoning dust exploding outward. Glossy, thick tomato glaze clings to the textured surface, catching bright studio reflections. Dynamic phantom high-speed camera effect.</span></span></code></pre></div><p>解析：动态炸裂（<code>breaks in mid-air</code>）配合粉末飞溅（<code>seasoning dust exploding</code>），能瞬间生成「极度酥脆」的视觉冲击。</p><h2 id="三大黄金法则" tabindex="-1">三大黄金法则 <a class="header-anchor" href="#三大黄金法则" aria-label="Permalink to &quot;三大黄金法则&quot;">​</a></h2><ol><li><strong>加词加在「动作」上</strong>：动词（<code>dripping, exploding, sizzling, wafting</code>）比形容词（<code>yummy, delicious</code>）管用 100 倍。</li><li><strong>控制光影与材质</strong>：善用 <code>backlit</code>（逆光）、<code>glossy</code>（镜面高光）、<code>amber tone</code>（琥珀色调），Veo 对光影关键词非常敏感。</li><li><strong>指定摄影参数</strong>：加 <code>Macro lens</code>、<code>120fps slow-motion</code>、<code>Phantom camera effect</code>，Veo 会自动套用商业广告级别的镜头调性。</li></ol><hr><p>关联：语言选择的分工见 <a href="/tools/gemini-prompt-language">中文还是英文</a>；这类「物理还原」词落地到材质一致性见 <a href="/tools/gemini-food-material">食品材质不漂移</a> 的 Material Tokens 写法。</p>',19)])])}const h=t(d,[["render",s]]);export{g as __pageData,h as default};
